// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Set up: call rely to authorize msg.sender (the test contract)
        c.rely(address(this));
        // Now deny the same address - in reference sets wards to 0, buggy sets to 1
        c.deny(address(this));
        // Call allowance to trigger the auth check in the underlying share call
        // The auth modifier will check wards[msg.sender]
        // Reference: wards[address(this)] = 0, so auth reverts => allowance reverts
        // Buggy: wards[address(this)] = 1, so auth passes => allowance proceeds
        bool ok;
        try c.allowance(address(0), address(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference (correct) contract, allowance should revert because deny removed auth
        // In buggy version, allowance succeeds (which is wrong)
        // So assert false for the reference, true for buggy
        // But our assertion must hold for reference and break for buggy
        // So we assert that the call reverts (ok == false)
        assertTrue(!ok, "allowance should have reverted");
    }
}

