pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Initially, msg.sender (this) is wards[this] = 1
        // Use deny to revoke own authorization
        c.deny(address(this));
        // Now try a privileged action: mint (only auth). Reference should revert, buggy should succeed.
        bool ok;
        try c.mint(address(0x1234), 100) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, deny sets wards[this]=0, so mint reverts => ok=false
        // In the bug, deny sets wards[this]=1, so mint succeeds => ok=true
        // We assert the reference behavior: mint should revert => ok == false
        assertTrue(!ok);
    }
}

