pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Call allowance to trigger the delegatecall to share.allowance with appended msg.sender
        c.allowance(address(this), address(0));
        // After that call, we check wards[address(this)]:
        // In the reference rely sets wards to 1, but the bug's rely sets to 0.
        // Since allowance does not change wards we need to call rely after to test the difference.
        // We call rely on address(this) which is the deployer and already ward = 1.
        // In reference rely does nothing but keeps wards = 1; in bug rely sets to 0.
        // So we assert that wards[address(this)] == 1 (reference) or == 0 (bug).
        // To expose the bug we call rely again, then check.
        c.rely(address(this));
        // Now reference: wards[address(this)] == 1, bug: wards[address(this)] == 0
        assertTrue(c.wards(address(this)) == 1);
    }
}

